<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { api, errorMessage, jsonRequest } from "@/api/client";
import type { LocationSummary, ObservationRecord, TripDetail as TripDetailType, TripSummary } from "@/api/types";
import TripDetail from "@/components/trips/TripDetail.vue";
import TripForm from "@/components/trips/TripForm.vue";

const route = useRoute(); const router = useRouter();
const items = ref<TripSummary[]>([]); const year = ref(""); const month = ref(""); const locationId = ref(""); const sort = ref<"asc" | "desc">("asc");
const loading = ref(true); const error = ref(""); const detailLoading = ref(false);
const detail = ref<TripDetailType | null>(null); const dialog = ref<HTMLDialogElement>(); const coverDialog = ref<HTMLDialogElement>(); const coverStatus = ref("请选择一笔观察记录。");
const locationsArchive = ref<LocationSummary[]>([]); const formDialog = ref<HTMLDialogElement>(); const formOpen = ref(false); const editing = ref<TripDetailType | null>(null);
const linkDialog = ref<HTMLDialogElement>(); const linkOpen = ref(false); const eligibleObservations = ref<ObservationRecord[]>([]); const linkedIds = ref<number[]>([]); const linkStatus = ref("");
const years = computed(() => [...new Set(items.value.map((item) => item.started_at.slice(0, 4)))].sort());
const months = computed(() => [...new Set(items.value.filter((item) => !year.value || item.started_at.startsWith(`${year.value}-`)).map((item) => item.started_at.slice(5, 7)))].sort());
const locations = computed(() => { const map = new Map<number, string>(); items.value.forEach((item) => (item.locations || [item.location]).forEach((location) => map.set(location.id, location.name))); return [...map].map(([id, name]) => ({ id, name })); });
const filtered = computed(() => items.value.filter((item) => (!year.value || item.started_at.slice(0, 4) === year.value) && (!month.value || item.started_at.slice(5, 7) === month.value) && (!locationId.value || (item.locations || [item.location]).some((location) => String(location.id) === locationId.value))).sort((a, b) => a.started_at.localeCompare(b.started_at) * (sort.value === "desc" ? -1 : 1)));
const groups = computed(() => { const map = new Map<string, TripSummary[]>(); filtered.value.forEach((item) => { const key = item.started_at.slice(0, 7); if (!map.has(key)) map.set(key, []); map.get(key)?.push(item); }); return [...map].map(([key, trips]) => ({ key, trips })); });
const countLabel = computed(() => filtered.value.length === items.value.length ? items.value.length : `${filtered.value.length}/${items.value.length}`);
watch(year, () => { if (!months.value.includes(month.value)) month.value = ""; });
function dateTime(value: string): string { return value.replace("T", " "); }
async function load(): Promise<void> { loading.value = true; error.value = ""; try { [items.value, locationsArchive.value] = await Promise.all([api<TripSummary[]>("/api/trips"), api<LocationSummary[]>("/api/locations")]); } catch (caught) { error.value = errorMessage(caught); } finally { loading.value = false; } }
async function open(id: number): Promise<void> { detailLoading.value = true; detail.value = null; await nextTick(); if (!dialog.value?.open) dialog.value?.showModal(); try { detail.value = await api<TripDetailType>(`/api/trips/${id}`); const query = { ...route.query }; delete query.new; await router.replace({ query: { ...query, trip: String(id) } }); } catch (caught) { error.value = errorMessage(caught); dialog.value?.close(); } finally { detailLoading.value = false; } }
function close(): void { dialog.value?.close(); detail.value = null; const next = { ...route.query }; delete next.trip; void router.replace({ query: next }); }
function reset(): void { year.value = ""; month.value = ""; locationId.value = ""; sort.value = "asc"; }
async function openForm(trip: TripDetailType | null = null): Promise<void> { editing.value = trip; formOpen.value = true; await nextTick(); formDialog.value?.showModal(); }
function hideForm(): void { formDialog.value?.close(); formOpen.value = false; editing.value = null; }
function closeForm(): void { hideForm(); if (route.query.new) { const query = { ...route.query }; delete query.new; void router.replace({ query }); } }
async function formSaved(saved: TripDetailType): Promise<void> { hideForm(); await load(); await open(saved.id); }
async function openLink(): Promise<void> { if (!detail.value) return; linkStatus.value = "正在读取观察记录…"; linkOpen.value = true; await nextTick(); linkDialog.value?.showModal(); try { const all = await api<ObservationRecord[]>("/api/observations"); const locationIds = new Set(detail.value.locations.map((item) => item.id)); eligibleObservations.value = all.filter((item) => item.trip?.id === detail.value?.id || (!item.trip && detail.value && detail.value.started_at <= item.observed_at && item.observed_at <= detail.value.ended_at && (!item.location || locationIds.has(item.location.id)))); linkedIds.value = detail.value.observations.map((item) => item.id); linkStatus.value = ""; } catch (caught) { linkStatus.value = errorMessage(caught); } }
function closeLink(): void { linkDialog.value?.close(); linkOpen.value = false; }
async function saveLinks(): Promise<void> { if (!detail.value) return; linkStatus.value = "正在保存关联…"; try { const updated = await api<TripDetailType>(`/api/trips/${detail.value.id}/observations`, jsonRequest("PUT", { observation_ids: linkedIds.value })); closeLink(); await load(); await open(updated.id); } catch (caught) { linkStatus.value = errorMessage(caught); } }
function openCover(): void { coverStatus.value = detail.value?.observations.length ? `从本次远征的 ${detail.value.observations.length} 笔观察中选择一张照片。` : "本次远征尚未关联带照片的观察记录。"; coverDialog.value?.showModal(); }
async function chooseCover(observation: ObservationRecord): Promise<void> { if (!detail.value) return; coverStatus.value = "正在更换远征封面……"; try { await api(`/api/trips/${detail.value.id}/cover`, jsonRequest("PUT", { observation_id: observation.id })); coverDialog.value?.close(); await Promise.all([load(), open(detail.value.id)]); } catch (caught) { coverStatus.value = errorMessage(caught); } }
async function remove(): Promise<void> { if (!detail.value || !confirm("删除远征只会解除观察关联，不会删除任何观察记录。确定删除吗？")) return; try { await api(`/api/trips/${detail.value.id}`, { method: "DELETE" }); close(); await load(); } catch (caught) { error.value = errorMessage(caught); } }
onMounted(async () => { await load(); const requested = Number(route.query.trip); if (requested && items.value.some((item) => item.id === requested)) await open(requested); else if (route.query.new === "1") await openForm(); });
</script>

<template>
  <main class="v2-archive-layout"><aside class="v2-archive-sidebar"><div class="v2-book-tab">EXPEDITION LOG</div><p class="v2-kicker">外出调查卷宗</p><h1>远征日志</h1><p class="v2-filter-intro">将同一次外出中的照片装订为旅程，回顾到访区域、持续时间与获得的物种情报。</p><label for="vue-trip-year">年份</label><select id="vue-trip-year" v-model="year"><option value="">全部年份</option><option v-for="item in years" :key="item" :value="item">{{ item }}年</option></select><label for="vue-trip-month">月份</label><select id="vue-trip-month" v-model="month"><option value="">全部月份</option><option v-for="item in months" :key="item" :value="item">{{ Number(item) }}月</option></select><label for="vue-trip-location">调查区域</label><select id="vue-trip-location" v-model="locationId"><option value="">全部区域</option><option v-for="item in locations" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select><label for="vue-trip-sort">装订顺序</label><select id="vue-trip-sort" v-model="sort"><option value="asc">从早到晚</option><option value="desc">从晚到早</option></select><button class="v2-filter-reset" type="button" @click="reset">清除检索条件</button><div class="v2-book-count"><strong>{{ countLabel }}</strong><span>卷远征日志</span></div></aside>
    <section class="v2-archive-content"><header class="v2-dex-header"><div><p class="v2-kicker">外出卷宗</p><h2>沿着路线重温探索</h2></div><button class="v2-new-entry" type="button" @click="openForm()">＋ 创建远征</button></header><p v-if="loading" class="v2-loading">正在装订远征日志…</p><p v-else-if="error" class="v2-loading">{{ error }}</p><div v-else class="v2-record-groups"><section v-for="group in groups" :key="group.key" class="v2-month-section"><header><div><span>{{ group.key.slice(0, 4) }}</span><h3>{{ Number(group.key.slice(5, 7)) }}月远征卷宗</h3></div><b>{{ group.trips.length }} 卷</b></header><div class="v2-expedition-grid"><button v-for="item in group.trips" :key="item.id" class="v2-expedition-card" type="button" @click="open(item.id)"><span class="v2-expedition-photo"><img v-if="item.cover_url" :src="item.cover_url" alt="" loading="lazy" /><i v-else>⌁</i><b>{{ item.catalog_number }}</b></span><span class="v2-expedition-copy"><small>{{ item.location.name }}</small><strong>{{ item.name }}</strong><em>{{ dateTime(item.started_at) }} — {{ dateTime(item.ended_at) }}</em><p>{{ item.notes || "本次远征没有附加备注。" }}</p><span class="v2-card-stat-grid"><article><strong>{{ item.species_count }}</strong><span>种</span></article><article><strong>{{ item.genus_count }}</strong><span>属</span></article><article><strong>{{ item.family_count }}</strong><span>科</span></article><article><strong>{{ item.observation_count }}</strong><span>记录</span></article></span></span></button></div></section></div><div v-if="!loading && !error && !filtered.length" class="v2-empty"><strong>没有符合条件的远征</strong><span>换一个月份或区域试试。</span></div></section></main>
  <dialog ref="dialog" class="v2-archive-dialog" @click.self="close"><p v-if="detailLoading" class="v2-loading v2-dossier-loading">正在调取远征卷宗…</p><TripDetail v-if="detail" :detail="detail" @close="close" @edit="openForm(detail)" @link="openLink" @edit-observations="openLink" @cover="openCover" @delete="remove" /></dialog>
  <dialog ref="formDialog" class="record-dialog trip-form-dialog" @click.self="closeForm"><TripForm v-if="formOpen" :trip="editing" :locations="locationsArchive" @close="closeForm" @saved="formSaved" /></dialog>
  <dialog ref="linkDialog" class="record-dialog trip-link-dialog" @click.self="closeLink"><form v-if="linkOpen" @submit.prevent="saveLinks"><header class="dialog-header"><div><p class="eyebrow">LINK OBSERVATIONS</p><h2>关联观察记录</h2></div><button type="button" class="icon-button" @click="closeLink">×</button></header><div class="form-scroll"><p class="section-note">显示本次远征已有记录，以及时间符合且地点相同或尚未关联地点的观察。取消勾选只会解除远征关联。</p><div class="location-link-list"><label v-for="item in eligibleObservations" :key="item.id" class="location-link-item"><input v-model="linkedIds" type="checkbox" :value="item.id" /><img :src="item.thumbnail_url" alt="" /><span><strong>{{ item.species_name }}</strong><small>{{ dateTime(item.observed_at) }} · {{ item.locality }}</small><em>{{ item.location ? item.location.name : "尚未关联地点；加入后自动关联主要地点" }}</em></span></label><p v-if="!eligibleObservations.length" class="compact-empty">没有符合时间和地点条件的可关联观察。</p></div></div><footer class="dialog-footer"><span>{{ linkStatus }}</span><button type="submit" class="primary-button">保存关联</button></footer></form></dialog>
  <dialog ref="coverDialog" class="v2-home-cover-dialog" @click.self="coverDialog?.close()"><header><div><p class="v2-kicker">远征封面</p><h2>更换封面</h2></div><button class="v2-dossier-close" type="button" aria-label="关闭" @click="coverDialog?.close()">×</button></header><div class="v2-home-cover-toolbar"><p>{{ coverStatus }}</p></div><div class="v2-home-cover-grid"><button v-for="observation in detail?.observations || []" :key="observation.id" class="v2-home-cover-card" :class="{ 'is-selected': observation.id === detail?.cover_observation_id }" type="button" :disabled="observation.id === detail?.cover_observation_id" @click="chooseCover(observation)"><img :src="observation.thumbnail_url" alt="" /><span><b>{{ observation.species_name }}</b><small>{{ dateTime(observation.observed_at) }}</small></span><em>{{ observation.id === detail?.cover_observation_id ? "当前封面" : "选作封面" }}</em></button></div></dialog>
</template>
